// CR 038: the vertical world's movement goldens (generated by
// golden/vertical.ts on worldgen.wasm, replayed by the Go step in
// server/pkg/movement/vertical_golden_test.go) reproduce bit-exactly.
import { existsSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { goldenPath, wasmPath } from './golden/io';
import { replayVertical, VERTICAL_SCENARIOS, verticalGround, type VerticalGolden } from './golden/vertical';
import { WP10_SEED } from './golden/wp10';
import { loadWorldgenGround } from './worldgenGround';

const haveWasm = existsSync(wasmPath);
describe.skipIf(!haveWasm)('CR 038 vertical goldens (worldgen.wasm, seed 20261108)', async () => {
  const ground = haveWasm ? await loadWorldgenGround(readFileSync(wasmPath), WP10_SEED) : null;
  const vw = ground ? verticalGround(ground) : null;
  for (const name of VERTICAL_SCENARIOS) {
    it(`${name}: stepMovement on VerticalGroundCore reproduces the committed golden`, () => {
      const p = goldenPath(`pt2_vertical_${name}`);
      if (!existsSync(p)) return;
      const file = JSON.parse(readFileSync(p, 'utf8')) as VerticalGolden;
      if (file.ground.genVersion !== ground!.wg.genVersion) return;
      const states = replayVertical(file, vw!);
      expect(states.length).toBe(file.states.length);
      for (let i = 0; i < states.length; i++) {
        if (file.states[i].some((v, k) => v !== states[i][k])) {
          throw new Error(`${name} step ${i + 1} differs: golden ${JSON.stringify(file.states[i])} vs now ${JSON.stringify(states[i])} (a generator change? npm run golden -w client)`);
        }
      }
    });
  }
});
